/*! nav v1.0.0 - Unlicensed - inspired by turbolinks and instant.page */

var nav = window.nav || (() => {
  const TTL = 10_000;
  const preloads = new Map();

  let current = location.pathname + location.search;

  const link_of = (e) => e.target.closest?.("a[href]");

  const eligible = (a) =>
    a && a.href && a.origin == location.origin &&
    !a.target && !a.hasAttribute("download") && !("native" in a.dataset) &&
    !(a.hash && a.pathname + a.search == location.pathname + location.search);

  const request = (url) =>
    fetch(url, { headers: { Accept: "text/html" } })
      .then(async (response) => ({ response, html: await response.text() }));

  const loaded = (href) =>
    [...document.styleSheets].some((sheet) => sheet.href == href);

  const warm = (href) => new Promise((done) => {
    const link = document.createElement("link");
    link.rel = "preload";
    link.as = "style";
    link.href = href;
    link.onload = link.onerror = () => done();
    document.head.append(link);
    setTimeout(done, 500);
  });

  const warm_styles = (html) => {
    const doc = new DOMParser().parseFromString(html, "text/html");
    const hrefs = [...doc.querySelectorAll("link[rel=stylesheet]")].map((link) => link.href);
    return Promise.all(hrefs.filter((href) => !loaded(href)).map(warm));
  };

  const preload = (url) => {
    const hit = preloads.get(url);
    if(hit && performance.now() - hit.time < TTL) return hit.promise;

    const promise = request(url);
    preloads.set(url, { promise, time: performance.now() });
    promise.then(({ html }) => warm_styles(html), () => preloads.delete(url));
    return promise;
  };

  const remember_state = () => {
    const focus = xhtml.focused(document.documentElement);
    const query = [...document.querySelectorAll("input[type=search][name]")]
      .map((node) => [node.name, node.value]);
    history.replaceState({ ...history.state, focus, query }, "", location.href);
  };

  const query_url = (href, query) => {
    const url = new URL(href);
    for(const [name, value] of query || []) url.searchParams.set(name, value);
    return url;
  };

  const render = async (response, html, push = true) => {
    await warm_styles(html);

    if(push) {
      remember_state();
      if(response.url != location.href) history.pushState(null, "", response.url);
    }

    current = location.pathname + location.search;
    xhtml.swap(document.documentElement, html);
    if(push) scrollTo(0, 0);
  };

  const navigate = async (url, push = true, fallback = url) => {
    let exchange;
    try { exchange = await preload(url); }
    catch { return location.assign(fallback); }
    preloads.delete(url);

    const { response, html } = exchange;
    const is_html = (response.headers.get("Content-Type") || "").includes("text/html");
    if(!response.ok || !is_html) return location.assign(fallback);

    return render(response, html, push);
  };

  const preload_target = (e) => {
    const a = link_of(e);
    if(eligible(a)) preload(a.href);
  };

  const follow = (e) => {
    if(e.defaultPrevented || e.button != 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;

    const a = link_of(e);
    if(!eligible(a)) return;

    e.preventDefault();
    navigate(a.href);
  };

  const traverse = async () => {
    if(location.pathname + location.search == current) return;

    const { focus, query } = history.state || {};
    await navigate(query_url(location.href, query), false, location.href);
    if(focus) xhtml.refocus(document.documentElement, focus);
  };

  document.addEventListener("mouseover", preload_target, { passive: true });
  document.addEventListener("touchstart", preload_target, { passive: true });
  document.addEventListener("click", follow);
  addEventListener("popstate", traverse);

  return { navigate, render };
})();
